#!/usr/bin/env python3

import re
import sys

def extract_hex_from_xxd(input_file, output_file):
    with open(input_file, 'r') as f:
        lines = f.readlines()

    binary_data = bytearray()

    for line in lines:
        # Extract the hex values between the first two pipe characters
        match = re.match(r'[0-9a-f]{8}\s+((?:[0-9a-f]{2}\s+){1,16}).*', line)
        if match:
            hex_part = match.group(1).strip()
            # Convert hex string to bytes
            hex_values = hex_part.split()
            for hex_val in hex_values:
                binary_data.append(int(hex_val, 16))

    with open(output_file, 'wb') as f:
        f.write(binary_data)

    return len(binary_data)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <input_file> <output_file>")
        sys.exit(1)

    try:
        bytes_written = extract_hex_from_xxd(sys.argv[1], sys.argv[2])
        print(f"Successfully converted {sys.argv[1]} to {sys.argv[2]}")
        print(f"Wrote {bytes_written} bytes")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

