#!/usr/bin/env python3
import sys
import binascii
import string
import itertools

def try_xor_decode(data, key_byte):
    result = bytearray()
    for i in range(len(data)):
        result.append(data[i] ^ key_byte)
    return bytes(result)

def try_single_byte_xor(data):
    best_score = 0
    best_key = 0
    best_result = b''

    for key in range(256):
        result = try_xor_decode(data, key)
        score = count_printable_chars(result)
        if score > best_score:
            best_score = score
            best_key = key
            best_result = result

    return best_key, best_result, best_score

def count_printable_chars(data):
    count = 0
    for byte in data:
        if 32 <= byte <= 126:  # ASCII printable characters
            count += 1
    return count

def try_rot(data, rot_value):
    result = bytearray()
    for byte in data:
        if 65 <= byte <= 90:  # A-Z
            result.append((byte - 65 + rot_value) % 26 + 65)
        elif 97 <= byte <= 122:  # a-z
            result.append((byte - 97 + rot_value) % 26 + 97)
        else:
            result.append(byte)
    return bytes(result)

def search_for_flag(data):
    # Look for "csawctf{" pattern
    for i in range(len(data) - 8):
        fragment = data[i:i+8].lower()
        if b'csawctf{' in fragment:
            start = i
            # Find the closing brace
            for j in range(i, min(i + 100, len(data))):
                if data[j] == ord('}'):
                    return data[i:j+1]
    return None

def try_caesar_on_flag_format(data):
    for rot in range(1, 26):
        rotated = try_rot(b"csawctf{", rot)
        for i in range(len(data) - 8):
            if data[i:i+8] == rotated:
                # Found a potential match, try to extract the full flag
                for j in range(i, min(i + 100, len(data))):
                    if data[j] == try_rot(b"}", rot)[0]:
                        # Potential flag found, now rotate it back
                        potential_flag = data[i:j+1]
                        original = try_rot(potential_flag, 26 - rot)
                        return original
    return None

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <input_file>")
        return

    with open(sys.argv[1], 'rb') as f:
        data = f.read()

    print(f"File size: {len(data)} bytes")

    # Try to find the flag directly
    flag = search_for_flag(data)
    if flag:
        print(f"Found flag: {flag.decode('utf-8', errors='ignore')}")

    # Try Caesar on flag format
    rotated_flag = try_caesar_on_flag_format(data)
    if rotated_flag:
        print(f"Found rotated flag: {rotated_flag.decode('utf-8', errors='ignore')}")

    # Try single-byte XOR
    best_key, best_result, best_score = try_single_byte_xor(data)
    print(f"Best XOR key: 0x{best_key:02x} ({best_key}) with {best_score}/{len(data)} printable characters")

    # Look for flag pattern in the XOR result
    flag_in_xor = search_for_flag(best_result)
    if flag_in_xor:
        print(f"Found flag in XOR result: {flag_in_xor.decode('utf-8', errors='ignore')}")

    # Save the result for inspection
    with open(f"/home/ctfplayer/best_xor_result.bin", 'wb') as f:
        f.write(best_result)

    # Search for other interesting patterns
    print("Looking for interesting patterns in XOR result...")
    try:
        readable_text = best_result.decode('utf-8', errors='ignore')
        lines = readable_text.split('\n')
        printable_lines = [line for line in lines if all(c in string.printable for c in line) and len(line) > 5]
        for line in printable_lines[:10]:
            print(f"  {line}")
    except Exception as e:
        print(f"Error decoding XOR result: {e}")

    print("\nTrying specific keys based on challenge hints...")

    # Try keys from "Hypokrinesthai" (ASCII values)
    hint_name = "Hypokrinesthai"
    for char in hint_name:
        key = ord(char)
        result = try_xor_decode(data, key)
        flag = search_for_flag(result)
        if flag:
            print(f"Found flag with key '{char}' (0x{key:02x}): {flag.decode('utf-8')}")

    # Try all combinations of characters from the word
    for i in range(1, 5):  # Try combinations of 1-4 characters
        for combo in itertools.permutations(hint_name, i):
            key_string = ''.join(combo)
            key_bytes = key_string.encode('utf-8')
            result = bytearray()
            for j in range(len(data)):
                result.append(data[j] ^ key_bytes[j % len(key_bytes)])

            flag = search_for_flag(bytes(result))
            if flag:
                print(f"Found flag with key '{key_string}': {flag.decode('utf-8')}")
                with open(f"/home/ctfplayer/decoded_with_{key_string}.bin", 'wb') as f:
                    f.write(result)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys

def try_xor_decode(data, key_byte):
    result = bytearray()
    for i in range(len(data)):
        result.append(data[i] ^ key_byte)
    return bytes(result)

def try_multi_byte_xor(data, key):
    result = bytearray()
    for i in range(len(data)):
        result.append(data[i] ^ key[i % len(key)])
    return bytes(result)

def count_printable_chars(data):
    count = 0
    for byte in data:
        if 32 <= byte <= 126:  # ASCII printable characters
            count += 1
    return count

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <input_file>")
        return

    with open(sys.argv[1], 'rb') as f:
        data = f.read()

    print(f"File size: {len(data)} bytes")

    # Try "Hypokrinesthai" as key
    key = "Hypokrinesthai".encode()
    result = try_multi_byte_xor(data, key)
    printable_count = count_printable_chars(result)
    print(f"XOR with 'Hypokrinesthai': {printable_count}/{len(data)} printable chars")

    with open("/home/ctfplayer/result_hypo.bin", "wb") as f:
        f.write(result)

    # Try "iahtsenirkopyH" (reversed) as key
    key = "iahtsenirkopyH".encode()
    result = try_multi_byte_xor(data, key)
    printable_count = count_printable_chars(result)
    print(f"XOR with 'iahtsenirkopyH': {printable_count}/{len(data)} printable chars")

    with open("/home/ctfplayer/result_reversed.bin", "wb") as f:
        f.write(result)

    # Check if we can find patterns in the results
    print("\nChecking for flag pattern in results...")
    for filename in ["/home/ctfplayer/result_hypo.bin", "/home/ctfplayer/result_reversed.bin"]:
        with open(filename, "rb") as f:
            content = f.read()

        try:
            text = content.decode('utf-8', errors='ignore')
            if "csawctf{" in text:
                print(f"Found potential flag in {filename}:")
                start = text.find("csawctf{")
                end = text.find("}", start)
                if end > start:
                    flag = text[start:end+1]
                    print(f"Flag: {flag}")

            lines = text.split('\n')
            print(f"First 5 lines from {filename}:")
            for i, line in enumerate(lines[:5]):
                print(f"  {line[:100]}")
        except Exception as e:
            print(f"Error processing {filename}: {e}")

if __name__ == "__main__":
    main()
